<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<title>MakeMyDemo.com — Motion Teaser</title>
<style>
  @font-face{font-family:'Inter';src:url('assets/Inter.ttf') format('truetype');}
  *{margin:0;padding:0;box-sizing:border-box;}
  html,body{background:#09090B;}
  #root{
    position:relative;width:1920px;height:1080px;overflow:hidden;
    font-family:'Inter',sans-serif;color:#FAFAFA;
    background:radial-gradient(1100px 760px at 50% 44%,#121215 0%,#09090B 62%);
  }
  .scene{position:absolute;inset:0;display:flex;flex-direction:column;align-items:center;justify-content:center;}
  #s2,#s3,#s4{opacity:0;}
  .rise{opacity:0;transform:translateY(44px);}
  .dot{color:#DFE104;}
  .h1{font-size:96px;font-weight:700;letter-spacing:-0.025em;line-height:1.06;text-align:center;}
  .h1 span{display:block;}
  .h2{font-size:76px;font-weight:700;letter-spacing:-0.02em;line-height:1.1;text-align:center;}

  #s1{gap:64px;}
  #bar{
    width:780px;height:92px;border:2px solid rgba(250,250,250,0.28);border-radius:46px;
    display:flex;align-items:center;justify-content:flex-end;padding-right:14px;
    position:relative;transform:scaleX(0);transform-origin:left center;
  }
  #caret{position:absolute;left:44px;top:50%;margin-top:-26px;width:3px;height:52px;background:#DFE104;}
  #pill{
    background:#DFE104;color:#09090B;font-size:26px;font-weight:700;
    padding:14px 36px;border-radius:32px;letter-spacing:0.01em;opacity:0;
  }

  #s2{gap:52px;}
  #card{
    width:960px;background:#121215;border:1px solid rgba(250,250,250,0.08);
    border-radius:26px;padding:26px;opacity:0;transform:translateY(60px);
  }
  #screen{position:relative;height:316px;background:#0C0C0F;border-radius:16px;border:1px solid rgba(250,250,250,0.05);overflow:hidden;}
  #play{position:absolute;left:50%;top:50%;transform:translate(-50%,-50%);opacity:0;}
  #wave{position:absolute;left:0;right:0;bottom:26px;display:flex;justify-content:center;gap:12px;align-items:flex-end;}
  #wave .b{width:8px;border-radius:4px;background:#DFE104;opacity:0.9;transform-origin:bottom center;}
  .meta{display:flex;justify-content:space-between;padding:24px 12px 4px;}
  .mrow{display:flex;align-items:center;gap:14px;font-size:25px;font-weight:500;color:rgba(250,250,250,0.88);opacity:0;transform:translateX(-24px);}

  #s3{gap:70px;}
  #track{position:relative;width:720px;height:8px;border-radius:4px;background:rgba(250,250,250,0.16);transform:scaleX(0);transform-origin:left center;}
  #fill{position:absolute;inset:0;border-radius:4px;background:#DFE104;transform:scaleX(0);transform-origin:left center;}
  #ph{position:absolute;left:0;top:50%;transform:translate(-50%,-50%);width:22px;height:22px;border-radius:50%;background:#DFE104;}
  #okwrap{display:flex;align-items:center;gap:20px;font-size:32px;font-weight:600;opacity:0;transform:translateY(30px);}

  #s4{gap:44px;}
  #s4 .h2{font-size:118px;}
  .lime{color:#DFE104;}
  #mark{font-size:58px;font-weight:800;letter-spacing:-0.01em;}
  #uline{width:460px;height:5px;border-radius:3px;background:#DFE104;transform:scaleX(0);transform-origin:center;}
</style>
</head>
<body>
<div id="root" data-composition-id="main" data-start="0" data-width="1920" data-height="1080" data-fps="24" data-duration="8">

  <section class="scene" id="s1" data-start="0" data-duration="2" data-track-index="0">
    <h1 class="h1">
      <span class="rise">Paste a public</span>
      <span class="rise">product URL<span class="dot">.</span></span>
    </h1>
    <div id="bar">
      <div id="caret"></div>
      <div id="pill">Paste</div>
    </div>
  </section>

  <section class="scene" id="s2" data-start="2" data-duration="2" data-track-index="0">
    <h2 class="h2 rise">Receive a video first cut<span class="dot">.</span></h2>
    <div id="card">
      <div id="screen">
        <svg id="play" width="104" height="104" viewBox="0 0 104 104">
          <circle cx="52" cy="52" r="50" fill="none" stroke="#DFE104" stroke-width="3"/>
          <path d="M43 34 L72 52 L43 70 Z" fill="#DFE104"/>
        </svg>
        <div id="wave">
          <div class="b" style="height:18px"></div>
          <div class="b" style="height:30px"></div>
          <div class="b" style="height:44px"></div>
          <div class="b" style="height:58px"></div>
          <div class="b" style="height:70px"></div>
          <div class="b" style="height:52px"></div>
          <div class="b" style="height:38px"></div>
          <div class="b" style="height:64px"></div>
          <div class="b" style="height:46px"></div>
          <div class="b" style="height:72px"></div>
          <div class="b" style="height:54px"></div>
          <div class="b" style="height:34px"></div>
          <div class="b" style="height:60px"></div>
          <div class="b" style="height:26px"></div>
        </div>
      </div>
      <div class="meta">
        <div class="mrow">
          <svg width="26" height="26" viewBox="0 0 24 24" fill="none" stroke="#DFE104" stroke-width="2" stroke-linecap="round"><path d="M5 6h14M5 12h14M5 18h8"/></svg>
          <span>AI-written script</span>
        </div>
        <div class="mrow">
          <svg width="26" height="26" viewBox="0 0 24 24" fill="none" stroke="#DFE104" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><rect x="3" y="6" width="18" height="12" rx="2"/><path d="M10 10.5l4 1.5-4 1.5z" fill="#DFE104" stroke="none"/></svg>
          <span>Product visuals</span>
        </div>
        <div class="mrow">
          <svg width="26" height="26" viewBox="0 0 24 24" fill="none" stroke="#DFE104" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M9 17V5l10-2v12"/><circle cx="6.5" cy="17" r="2.5"/><circle cx="16.5" cy="15" r="2.5"/></svg>
          <span>Music</span>
        </div>
      </div>
    </div>
  </section>

  <section class="scene" id="s3" data-start="4" data-duration="2" data-track-index="0">
    <h2 class="h2 rise">Review the cut<span class="dot">.</span></h2>
    <div id="track">
      <div id="fill"></div>
      <div id="ph"></div>
    </div>
    <div id="okwrap">
      <svg width="56" height="56" viewBox="0 0 56 56">
        <circle id="ck-c" cx="28" cy="28" r="25" fill="none" stroke="#DFE104" stroke-width="3" pathLength="1" stroke-dasharray="1" stroke-dashoffset="1" transform="rotate(-90 28 28)"/>
        <path id="ck-p" d="M17 29 L25 37 L40 21" fill="none" stroke="#DFE104" stroke-width="4" stroke-linecap="round" stroke-linejoin="round" pathLength="1" stroke-dasharray="1" stroke-dashoffset="1"/>
      </svg>
      <span>Ready to export</span>
    </div>
  </section>

  <section class="scene" id="s4" data-start="6" data-duration="2" data-track-index="0">
    <h2 class="h2 rise"><span>Export </span><span class="lime">MP4.</span></h2>
    <div id="mark" class="rise">MakeMyDemo<span class="lime">.com</span></div>
    <div id="uline"></div>
  </section>

</div>
<script src="assets/gsap.min.js"></script>
<script>
  window.__timelines = {};
  const tl = gsap.timeline({ paused: true, defaults: { ease: 'power3.out' } });

  tl.fromTo('#s1 .rise', { y: 44, opacity: 0 }, { y: 0, opacity: 1, duration: 0.5, stagger: 0.09 }, 0.05);
  tl.fromTo('#bar', { scaleX: 0 }, { scaleX: 1, duration: 0.45, transformOrigin: 'left center' }, 0.35);
  tl.fromTo('#pill', { scale: 0.6, opacity: 0 }, { scale: 1, opacity: 1, duration: 0.35, ease: 'back.out(2)' }, 0.75);
  tl.fromTo('#caret', { opacity: 1 }, { opacity: 0, duration: 0.28, yoyo: true, repeat: 5, ease: 'steps(1)' }, 0.55);
  tl.to('#pill', { scale: 0.92, duration: 0.12, ease: 'power2.in' }, 1.5);
  tl.to('#pill', { scale: 1, duration: 0.16 }, 1.62);
  tl.to('#bar', { borderColor: '#DFE104', duration: 0.2 }, 1.6);
  tl.to('#s1', { opacity: 0, y: -36, duration: 0.3, ease: 'power2.in' }, 1.7);

  tl.fromTo('#s2', { opacity: 0 }, { opacity: 1, duration: 0.3 }, 2.0);
  tl.fromTo('#s2 .rise', { y: 44, opacity: 0 }, { y: 0, opacity: 1, duration: 0.5 }, 2.1);
  tl.fromTo('#card', { y: 60, opacity: 0 }, { y: 0, opacity: 1, duration: 0.55 }, 2.25);
  tl.fromTo('#play', { scale: 0, opacity: 0 }, { scale: 1, opacity: 1, duration: 0.4, ease: 'back.out(2)' }, 2.6);
  tl.fromTo('.mrow', { x: -24, opacity: 0 }, { x: 0, opacity: 1, duration: 0.4, stagger: 0.1 }, 2.75);
  tl.fromTo('#wave .b', { scaleY: 1 }, { scaleY: 0.35, duration: 0.28, yoyo: true, repeat: 3, stagger: 0.05, ease: 'sine.inOut' }, 2.85);
  tl.to('#s2', { opacity: 0, y: -36, duration: 0.3, ease: 'power2.in' }, 3.7);

  tl.fromTo('#s3', { opacity: 0 }, { opacity: 1, duration: 0.3 }, 4.0);
  tl.fromTo('#s3 .rise', { y: 44, opacity: 0 }, { y: 0, opacity: 1, duration: 0.5 }, 4.1);
  tl.fromTo('#track', { scaleX: 0 }, { scaleX: 1, duration: 0.5, transformOrigin: 'left center' }, 4.3);
  tl.fromTo('#fill', { scaleX: 0 }, { scaleX: 1, duration: 0.8, transformOrigin: 'left center', ease: 'power1.inOut' }, 4.45);
  tl.fromTo('#ph', { x: 0 }, { x: 720, duration: 0.8, ease: 'power1.inOut' }, 4.45);
  tl.fromTo('#okwrap', { y: 30, opacity: 0 }, { y: 0, opacity: 1, duration: 0.4 }, 5.0);
  tl.fromTo('#ck-c', { strokeDashoffset: 1 }, { strokeDashoffset: 0, duration: 0.4, ease: 'power2.out' }, 5.1);
  tl.fromTo('#ck-p', { strokeDashoffset: 1 }, { strokeDashoffset: 0, duration: 0.25 }, 5.45);
  tl.to('#s3', { opacity: 0, y: -36, duration: 0.3, ease: 'power2.in' }, 5.7);

  tl.fromTo('#s4', { opacity: 0 }, { opacity: 1, duration: 0.3 }, 6.0);
  tl.fromTo('#s4 .rise', { y: 50, opacity: 0 }, { y: 0, opacity: 1, duration: 0.55, stagger: 0.1 }, 6.1);
  tl.fromTo('#uline', { scaleX: 0 }, { scaleX: 1, duration: 0.45, transformOrigin: 'center', ease: 'power2.inOut' }, 6.45);
  tl.to('#root', { opacity: 0.999, duration: 0.02 }, 7.98);

  window.__timelines['main'] = tl;
  window.__renderReady = true;
</script>
</body>
</html>
